import React, { useState } from 'react';
import './AdminPanel.css'; // Asegúrate de que los estilos estén bien configurados

function AdminPanel() {
  const [selectedSection, setSelectedSection] = useState('usuarios');
  const [users, setUsers] = useState([
    { id: 1, name: 'Juan Pérez', email: 'juan@example.com', role: 'usuario' },
    { id: 2, name: 'Ana Gómez', email: 'ana@example.com', role: 'administrador' },
    { id: 3, name: 'Luis Martínez', email: 'luis@example.com', role: 'usuario' },
  ]);

  const handleChangeRole = (id, newRole) => {
    setUsers(users.map(user => 
      user.id === id ? { ...user, role: newRole } : user
    ));
  };

  const handleDeleteUser = (id) => {
    setUsers(users.filter(user => user.id !== id));
  };

  const handleViewMore = (id) => {
    const user = users.find(u => u.id === id);
    alert(`Información de ${user.name}: ${user.email}, Rol: ${user.role}`);
  };

  return (
    <div className="admin-panel">
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li 
            onClick={() => setSelectedSection('usuarios')}
            className={selectedSection === 'usuarios' ? 'active' : ''}
          >
            Usuarios
          </li>
          <ul className={selectedSection === 'usuarios' ? 'submenu show' : 'submenu'}>
            <li onClick={() => setSelectedSection('gestionarUsuarios')}>Gestionar Usuarios</li>
          </ul>

          <li 
            onClick={() => setSelectedSection('productos')}
            className={selectedSection === 'productos' ? 'active' : ''}
          >
            Productos
          </li>
          <ul className={selectedSection === 'productos' ? 'submenu show' : 'submenu'}>
            <li>Agregar Producto</li>
            <li>Listar Productos</li>
          </ul>

          <li 
            onClick={() => setSelectedSection('ventas')}
            className={selectedSection === 'ventas' ? 'active' : ''}
          >
            Ventas
          </li>
          <ul className={selectedSection === 'ventas' ? 'submenu show' : 'submenu'}>
            <li>Listar Ventas</li>
          </ul>
        </ul>
      </div>

      <div className="main-content">
        {selectedSection === 'usuarios' && (
          <div>
            <h1>Gestión de Usuarios</h1>
            <div className="user-list">
              {users.map(user => (
                <div key={user.id} className="user-card">
                  <div className="user-info">
                    <span><strong>{user.name}</strong></span>
                    <span>{user.email}</span>
                    <span>Rol: {user.role}</span>
                  </div>
                  <div className="user-actions">
                    <button onClick={() => handleViewMore(user.id)}>Ver Más</button>
                    <button onClick={() => handleChangeRole(user.id, user.role === 'usuario' ? 'administrador' : 'usuario')}>
                      Cambiar Rol
                    </button>
                    <button onClick={() => handleDeleteUser(user.id)}>Dar de Baja</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {selectedSection === 'productos' && (
          <div>
            <h1>Gestión de Productos</h1>
            <p>Opciones: Agregar Producto, Listar Productos</p>
          </div>
        )}

        {selectedSection === 'ventas' && (
          <div>
            <h1>Ventas</h1>
            <p>Listar Ventas</p>
          </div>
        )}

        {selectedSection === 'gestionarUsuarios' && (
          <div>
            <h1>Gestionar Usuarios</h1>
            {/* Aquí puedes colocar la lógica para gestionar usuarios */}
          </div>
        )}
      </div>
    </div>
  );
}

export default AdminPanel;
